     /** Delay to wait after the given number of failed attempts (1 = the first attempt failed). */
     public Duration delayAfter(int failedAttempts) {
-        return base;
+        if (failedAttempts < 1) {
+            throw new IllegalArgumentException("failedAttempts must be >= 1");
+        }
+        Duration current = base;
+        for (int i = 1; i < failedAttempts; i++) {
+            Duration remaining;
+            try {
+                remaining = max.minus(current);
+            } catch (RuntimeException e) {
+                return max;
+            }
+            if (current.compareTo(remaining) > 0) {
+                return max;
+            }
+            try {
+                current = current.plus(current);
+            } catch (RuntimeException e) {
+                return max;
+            }
+            if (current.isNegative() || current.compareTo(max) >= 0) {
+                return max;
+            }
+        }
+        return current;
     }
 }
